"""``pluginlake secrets`` — list and read the secrets of a node."""

import sys
from pathlib import Path

from pluginlake.deploy.config import SecretKind, SecretSpec, load_init_config
from pluginlake.utils.logger import get_logger

logger = get_logger(__name__)


def _origin(spec: SecretSpec) -> str:
    """Secrets generated by setup are internal, secrets the operator or a secret manager supplies are external."""
    return "external" if spec.kind is SecretKind.EMPTY else "internal"


def _is_present(spec: SecretSpec, path: Path) -> bool:
    return path.is_file() and (spec.kind is SecretKind.EMPTY or path.stat().st_size > 0)


def run_secrets_list(home: Path) -> int:
    """Print the name, origin and presence of every secret, never the value.

    Args:
        home: The data folder (``PLUGINLAKE_HOME``).

    Returns:
        ``0`` if every internal secret is present and every external secret has content, ``1`` otherwise.
    """
    config = load_init_config()
    folder = home / config.secrets_folder
    failed = False
    for spec in config.secrets:
        present = _is_present(spec, folder / spec.name)
        # An external secret may be empty (optional), so it only fails when the file itself is missing.
        ok = present or (spec.kind is SecretKind.EMPTY and (folder / spec.name).is_file())
        failed = failed or not ok
        print(f"{'ok' if ok else 'MISSING':8}{_origin(spec):10}{spec.name}")
    return 1 if failed else 0


def run_secrets_get(home: Path, name: str) -> int:
    """Print the value of one secret if the current user may read it, and log the access without the value.

    Args:
        home: The data folder (``PLUGINLAKE_HOME``).
        name: Name of the secret.

    Returns:
        ``0`` on success, ``1`` if the secret is unknown, missing or not readable.
    """
    config = load_init_config()
    if name not in {spec.name for spec in config.secrets}:
        print(f"Unknown secret '{name}'.", file=sys.stderr)
        return 1
    try:
        value = (home / config.secrets_folder / name).read_text(encoding="utf-8")
    except OSError as error:
        print(f"Cannot read secret '{name}': {error.strerror}.", file=sys.stderr)
        return 1
    logger.info("Secret '%s' was read through the CLI.", name)
    print(value, end="")
    return 0
